-- Read-only post-check for 20270102140000_editions_payment_safeguards_2.sql. Every row should say ok = true.
select 'stray-subscription queue exists with RLS on' as check, count(*) = 1 as ok from pg_class where relname = 'edition_stripe_stray_subscriptions' and relrowsecurity;
select 'stray queue is not readable or writable by users' as check, count(*) = 0 as ok from information_schema.role_table_grants where table_name = 'edition_stripe_stray_subscriptions' and grantee in ('anon', 'authenticated', 'public');
select 'refund requests have retry columns (attempts, last failure, next attempt)' as check, count(*) = 3 as ok from information_schema.columns where table_schema = 'public' and table_name = 'edition_refund_requests' and column_name in ('attempts', 'last_error', 'next_attempt_at');
select 'exception kinds include duplicate_subscription and refund_failed' as check, count(*) = 1 as ok from pg_constraint where conrelid = 'public.edition_reconciliation_exceptions'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%duplicate_subscription%' and pg_get_constraintdef(oid) like '%refund_failed%';
select 'new payment functions are not callable by users' as check, count(*) = 0 as ok from pg_proc p where proname in ('edition_stripe_stray_next', 'edition_stripe_stray_mark', 'edition_refunds_next', 'edition_refund_request_mark', 'edition_payout_account_disconnected')
  and pronamespace = 'public'::regnamespace and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
select 'membership pay_prepare reports the existing subscription' as check, pg_get_functiondef('public.edition_membership_pay_prepare(uuid,text)'::regprocedure) like '%existing_subscription%' as ok;
select 'participation capacity check takes a lock per Edition' as check, pg_get_functiondef('public.edition_participation_pay_prepare(uuid,text)'::regprocedure) like '%pg_advisory_xact_lock%' as ok;
select 'abandoned payment attempts stop holding places and locking terms (hold window)' as check, pg_get_functiondef('public.edition_participation_pay_prepare(uuid,text)'::regprocedure) like '%payment_hold_minutes%' and pg_get_functiondef('public.edition_set_participation_terms(uuid,text,integer,text,text,date,integer,date)'::regprocedure) like '%payment_hold_minutes%' as ok;
select 'no open duplicate_subscription or refund_failed exception is being hidden (informational: expect 0 on a fresh release)' as check, count(*) = 0 as ok from public.edition_reconciliation_exceptions where kind in ('duplicate_subscription', 'refund_failed') and status = 'open';
